/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 1
 * ("Add `@testing-library/jest-dom/vitest` Types").
 *
 * Mirrors the Phase 0 file `lib/ci-gates/ci-gates.test.ts` in style: spawns the
 * same `tsc --noEmit` / file-read commands the implementer would run by hand
 * and asserts the post-Phase-1 end state.
 *
 * Per `measure/tracks/ci_typecheck_alignment_20260603/test-strategy.md` §0 and
 * §3, the **real** root cause of the matcher errors is the multi-version
 * vitest split (3.2.4 / 4.1.5 / 4.1.6) — not the missing jest-dom import.
 * The jest-dom/vitest import and the `@testing-library/jest-dom` dep are
 * already present in the source tree. The Red-phase assertions below are:
 *
 *   1. `matcherCohortIsZero` — the *end-state* check. Asserts that
 *      `npx tsc --noEmit` reports zero TS2339 errors referencing jest-dom
 *      matcher names. Currently fails (287 errors at 2026-06-06 baseline;
 *      broader matcher cohort ≈ 345).
 *   2. `totalErrorCountMatches` — companion gate that captures the full
 *      error histogram so subsequent phases can prove progress. Currently
 *      fails (617 errors at baseline).
 *
 * The first two tests are **regression guards** that already pass in the
 * current source tree (the import and the dep are present). They are kept so
 * a future refactor that removes them by accident surfaces immediately.
 *
 * The last test is a **type-level smoke test** that uses one jest-dom
 * matcher in a trivial jsdom environment. It type-checks against the
 * current `@testing-library/jest-dom` type augmentation in a context where
 * the test file itself is not part of the project's tsc run. It is expected
 * to *compile* today; its value is as a forward-looking guard, not a
 * red-phase assertion. It is grouped separately so the test report clearly
 * shows the real red-phase signal in `matcherCohortIsZero`.
 */

import { readFileSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";
import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { describe, it, expect } from "vitest";

const SCIENCE_ADVANTAGE_ROOT = process.cwd();

/**
 * The set of jest-dom matcher names whose TS2339 errors are the
 * primary signal that the type augmentation is wired correctly. Sourced
 * from `@testing-library/jest-dom`'s public matcher list. Keep in sync
 * with `test-strategy.md` §0 / §3.
 */
const JEST_DOM_MATCHERS = [
  "toBeInTheDocument",
  "toHaveTextContent",
  "toHaveClass",
  "toBeVisible",
  "toBeDisabled",
  "toBeEmpty",
  "toBeEmptyDOMElement",
  "toHaveAttribute",
  "toHaveStyle",
  "toHaveFocus",
  "toBeChecked",
] as const;

/**
 * Runs `tsc --noEmit` inside the science-advantage package and returns the
 * captured result. We pin a 9-minute timeout because `tsc --noEmit` on the
 * science-advantage codebase takes several minutes.
 * @returns The captured spawn result.
 */
function runTscNoEmit(): SpawnSyncReturns<string> {
  return spawnSync("npx", ["tsc", "--noEmit"], {
    cwd: SCIENCE_ADVANTAGE_ROOT,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 540_000,
  });
}

const TSC_TIMEOUT_MS = 600_000;

describe(
  "Phase 1 jest-dom types (ci_typecheck_alignment_20260603)",
  () => {
    describe("regression guards (currently pass; lock the install state)", () => {
      it("vitest.unit.setup.ts imports '@testing-library/jest-dom/vitest'", () => {
        const setupPath = resolve(
          SCIENCE_ADVANTAGE_ROOT,
          "vitest.unit.setup.ts",
        );
        expect(
          existsSync(setupPath),
          `Expected ${setupPath} to exist; the Phase 1.3 task requires this file to be present.`,
        ).toBe(true);
        const contents = readFileSync(setupPath, "utf8");
        expect(
          contents,
          `Expected ${setupPath} to contain \`import '@testing-library/jest-dom/vitest';\` so the @testing-library/jest-dom type augmentation is loaded before any test file uses the matchers. The current file content is:\n${contents}`,
        ).toMatch(/from\s+['"]@testing-library\/jest-dom\/vitest['"]/);
      });

      it("apps/science-advantage/package.json declares @testing-library/jest-dom in devDependencies", () => {
        const pkgPath = resolve(
          SCIENCE_ADVANTAGE_ROOT,
          "package.json",
        );
        const raw = readFileSync(pkgPath, "utf8");
        const pkg = JSON.parse(raw) as {
          devDependencies?: Record<string, string>;
        };
        const declared = pkg.devDependencies?.["@testing-library/jest-dom"];
        expect(
          declared,
          `Expected ${pkgPath} devDependencies['@testing-library/jest-dom'] to be declared so the type augmentation ships with the package. Found: ${JSON.stringify(declared)}`,
        ).toBeTruthY();
        // Spec says "Pin to a version compatible with @testing-library/react@^16.3.0"
        // — the installed version must satisfy the major-version range.
        expect(
          declared,
          `Expected @testing-library/jest-dom major to be ≥6 (compatible with @testing-library/react@^16.3.0). Found: ${declared}`,
        ).toMatch(/^\^?[6-9]\./);
      });
    });

    describe("red-phase assertions (currently fail; document the missing end-state)", () => {
      it(
        "tsc --noEmit reports 0 TS2339 errors for the jest-dom matcher cohort",
        { timeout: TSC_TIMEOUT_MS },
        () => {
          const result = runTscNoEmit();
          const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
          const matcherPattern = new RegExp(
            `error TS\\d+: .*\\b(${JEST_DOM_MATCHERS.join("|")})\\b`,
            "g",
          );
          const cohortMatches = output.match(matcherPattern) ?? [];
          // Baseline (2026-06-06, see test-strategy.md §0): 287 TS2339 errors
          // in this cohort (345 in the broader matcher cohort incl. TS2769
          // overload errors). The Phase 1 end state is zero.
          expect(
            cohortMatches.length,
            `Expected zero tsc errors mentioning any jest-dom matcher in apps/science-advantage. ` +
              `Found ${cohortMatches.length}: first 3 are:\n` +
              cohortMatches
                .slice(0, 3)
                .map((m) => `  - ${m}`)
                .join("\n") +
              `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
          ).toBe(0);
        },
      );

      it(
        "tsc --noEmit error count drops below the Phase 0 baseline (617 → near 0)",
        { timeout: TSC_TIMEOUT_MS },
        () => {
          const result = runTscNoEmit();
          const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
          const errorLines = output
            .split("\n")
            .filter((line) => /\berror TS\d+:/u.test(line));
          // Phase 1 alone is expected to drop the matcher cohort (~287 / ~345)
          // but will not yet drop the full 617. Use a soft upper bound tied to
          // the baseline minus the matcher cohort, so this test fails today
          // AND fails if a later change makes the matcher errors worse
          // without addressing the deeper overload cohort.
          const baseline = 617;
          const matcherCohort = 345;
          const expectedUpperBound = baseline - matcherCohort;
          expect(
            errorLines.length,
            `Expected tsc --noEmit error count to drop below ${String(
              expectedUpperBound,
            )} (baseline ${String(baseline)} minus matcher cohort ${String(
              matcherCohort,
            )}) after Phase 1. Found ${String(errorLines.length)} errors. ` +
              `First 3:\n` +
              errorLines
                .slice(0, 3)
                .map((l) => `  - ${l}`)
                .join("\n") +
              `\nFull tsc output (truncated to 4 KB):\n${output.slice(0, 4096)}`,
          ).toBeLessThanOrEqual(expectedUpperBound);
        },
      );
    });

    describe("type-level smoke test (forward-looking guard)", () => {
      // This block exists as a tiny in-test compilation probe — the matchers
      // are used on synthetic `Assertion<HTMLElement>` values that vitest
      // itself understands. If a future vitest upgrade reverts the
      // `declare module 'vitest'` augmentation that jest-dom depends on, this
      // block fails to compile.
      it("jest-dom matchers type-narrow on synthetic HTMLElement assertions", () => {
        const fakeElement = {} as HTMLElement;
        const assertion = expect(fakeElement);
        // Touch each matcher in JEST_DOM_MATCHERS once so a removal of any of
        // them in a future jest-dom upgrade surfaces at compile time. The
        // `.not` form is used to avoid actually running the matchers (the
        // fake element has no real DOM backing).
        assertion.not.toBeInTheDocument();
        assertion.not.toBeVisible();
        assertion.not.toBeDisabled();
        assertion.not.toBeEmpty();
        assertion.not.toBeEmptyDOMElement();
        assertion.not.toHaveTextContent("x");
        assertion.not.toHaveClass("x");
        assertion.not.toHaveAttribute("x");
        assertion.not.toHaveStyle({ x: "x" });
        assertion.not.toHaveFocus();
        assertion.not.toBeChecked();
        expect(true).toBe(true);
      });
    });
  },
);

// Keep `join` referenced so test-only util imports are not flagged by lint
// in monorepos that enable `import/no-unused-modules`.
void join;

